var d;try{d=JSON.parse(msg.payload);}catch(e){node.error('PKI parse: '+e);return null;}
var keys=(d.recent_session_keys_b64||[]).slice().reverse();
var ak=d.active_session_key_b64;
if(ak&&keys.indexOf(ak)<0)keys.unshift(ak);
if(keys.length){flow.set('pki_keys',keys);node.status({fill:'green',shape:'dot',text:keys.length+' chave(s)'});}
else node.status({fill:'yellow',shape:'ring',text:'sem chave no PKI'});
return null;

const crypto=global.get('crypto');
var keys=flow.get('pki_keys')||[];
if(!keys.length){node.status({fill:'red',shape:'ring',text:'sem chave'});return null;}
var wire=Buffer.from(String(msg.payload).trim(),'base64');
if(wire.length<28){return null;}
var iv=wire.subarray(0,12),tag=wire.subarray(wire.length-16),ct=wire.subarray(12,wire.length-16);
for(var i=0;i<keys.length;i++){
  try{
    var key=Buffer.from(keys[i],'base64').subarray(0,16);
    var dec=crypto.createDecipheriv('aes-128-gcm',key,iv);dec.setAuthTag(tag);
    var pt=Buffer.concat([dec.update(ct),dec.final()]);
    msg.payload=JSON.parse(pt.toString('utf8'));
    var parts=String(msg.topic).split('/');
    if(parts.length>=2){if(parts[2]==='estado')flow.set('relay_mac',parts[1]);else flow.set('node_mac',parts[1]);}
    node.status({fill:'green',shape:'dot',text:'OK'});
    return msg;
  }catch(e){}
}
node.status({fill:'yellow',shape:'ring',text:'decrypt falhou'});return null;

