const crypto=global.get('crypto');
var keys=flow.get('pki_keys')||[];
var mac=flow.get('relay_mac')||flow.get('node_mac');
if(!keys.length||!mac){node.warn('sem chave ou MAC de relay');return null;}
var key=Buffer.from(keys[0],'base64').subarray(0,16);
var iv=crypto.randomBytes(12);
var cmd=Buffer.from(JSON.stringify({command:msg.payload}),'utf8');
var c=crypto.createCipheriv('aes-128-gcm',key,iv);
var ct=Buffer.concat([c.update(cmd),c.final()]);var tag=c.getAuthTag();
msg.payload=Buffer.concat([iv,ct,tag]).toString('base64');
msg.topic='CHARLIE/'+mac+'/comando';return msg;
